use vstd::prelude::*;

verus! {

/// Mathematical popcount on natural numbers.
spec fn popcount_nat(n: nat) -> nat
    decreases n
{
    if n == 0 {
        0
    } else {
        (n % 2) + popcount_nat(n / 2)
    }
}

/// Convenience: popcount specialized to u8 inputs.
spec fn popcount_u8(n: u8) -> nat {
    popcount_nat(n as nat)
}

fn solve(n: u8) -> (r: u8)
    requires
        // u8 input is always in 0..=255, stated explicitly:
        n as nat <= 255,
    ensures
        // Result equals the mathematical popcount of n.
        r as nat == popcount_u8(n),
        // Result fits in u8 and is at most 8 for 8-bit inputs.
        r as nat <= 8,
{
    let mut x: u8 = n;
    let mut count: u8 = 0;

    while x != 0
        invariant
            // Relate current state to original input:
            count as nat + popcount_u8(x) == popcount_u8(n),
            count as nat <= 8,
            x as nat <= 255,
        decreases x as nat
    {
        count = count + (x & 1);
        x = x >> 1;
    }

    r = count;
}

} // verus!